import pytest

from reverse_words import reverse_words


class TestReverseWords:
    """Tests for the reverse_words function."""

    @pytest.mark.parametrize(
        "sentence, expected",
        [
            ("I love Python", "Python love I"),
            ("Hello World", "World Hello"),
            ("one two three four", "four three two one"),
            ("single", "single"),
        ],
    )
    def test_reverse_words_happy_path(self, sentence, expected):
        """Reverse the order of words for normal, well-formed sentences."""
        assert reverse_words(sentence) == expected

    @pytest.mark.parametrize(
        "sentence, expected",
        [
            ("I     Love          Python", "Python Love I"),
            ("  leading and trailing  ", "trailing and leading"),
            ("a\tb\nc", "c b a"),
            ("   ", ""),
            ("", ""),
        ],
    )
    def test_reverse_words_whitespace_handling(self, sentence, expected):
        """Collapse extra whitespace and handle empty/whitespace-only input."""
        assert reverse_words(sentence) == expected

    def test_reverse_words_preserves_word_characters(self):
        """Ensure punctuation and case within words are preserved."""
        assert reverse_words("Hello, World!") == "World! Hello,"

    def test_reverse_words_returns_string(self):
        """The function must always return a str instance."""
        result = reverse_words("some words here")
        assert isinstance(result, str)

from collections import Counter

import pytest

from word_occurrence import word_occurrence


class TestWordOccurrence:
    """Test suite for word_occurrence."""

    @pytest.mark.parametrize(
        ("sentence", "expected"),
        [
            ("a b A b c b d b d e f e g e h e i e j e 0",
             Counter("a b A b c b d b d e f e g e h e i e j e 0".split())),
            ("Two  spaces", {"Two": 1, "spaces": 1}),
            ("hello", {"hello": 1}),
            ("one two three", {"one": 1, "two": 1, "three": 1}),
        ],
    )
    def test_word_occurrence_happy_path(self, sentence, expected):
        """Test that word counts match expected values for normal input."""
        result = word_occurrence(sentence)
        assert dict(result) == dict(expected)

    def test_word_occurrence_repeated_words(self):
        """Test that repeated words are counted correctly."""
        result = word_occurrence("foo foo foo bar bar baz")
        assert dict(result) == {"foo": 3, "bar": 2, "baz": 1}

    def test_word_occurrence_empty_string(self):
        """Test that an empty string returns an empty dict."""
        assert dict(word_occurrence("")) == {}

    def test_word_occurrence_whitespace_only(self):
        """Test that whitespace-only input returns an empty dict."""
        assert dict(word_occurrence("   \t\n  ")) == {}

    def test_word_occurrence_leading_trailing_spaces(self):
        """Test that leading/trailing whitespace is ignored by split()."""
        result = word_occurrence("  hello   world  ")
        assert dict(result) == {"hello": 1, "world": 1}

    def test_word_occurrence_case_sensitive(self):
        """Test that words differing only by case are treated as distinct."""
        result = word_occurrence("Hello hello HELLO")
        assert dict(result) == {"Hello": 1, "hello": 1, "HELLO": 1}

    def test_word_occurrence_returns_defaultdict(self):
        """Test that the return value is a defaultdict of int."""
        result = word_occurrence("a b")
        assert isinstance(result, dict)
        assert result["missing"] == 0

    def test_word_occurrence_matches_counter(self):
        """Test that results match collections.Counter for a mixed sentence."""
        sentence = "the quick brown fox jumps over the lazy dog the"
        result = word_occurrence(sentence)
        assert dict(result) == dict(Counter(sentence.split()))

import pytest

from decimal_to_binary import (
    decimal_to_binary_iterative,
    decimal_to_binary_recursive,
    decimal_to_binary_recursive_helper,
)


class TestDecimalToBinaryIterative:
    """Tests for decimal_to_binary_iterative."""

    @pytest.mark.parametrize(
        ("num", "expected"),
        [
            (0, "0b0"),
            (1, "0b1"),
            (2, "0b10"),
            (7, "0b111"),
            (35, "0b100011"),
            (1000, "0b1111101000"),
        ],
    )
    def test_positive_integers(self, num, expected):
        """Positive integers should convert to their binary representation."""
        assert decimal_to_binary_iterative(num) == expected

    @pytest.mark.parametrize(
        ("num", "expected"),
        [
            (-1, "-0b1"),
            (-2, "-0b10"),
            (-7, "-0b111"),
            (-35, "-0b100011"),
        ],
    )
    def test_negative_integers(self, num, expected):
        """Negative integers should produce a '-0b' prefixed binary string."""
        assert decimal_to_binary_iterative(num) == expected

    def test_zero_edge_case(self):
        """Zero is a boundary value and should return '0b0'."""
        assert decimal_to_binary_iterative(0) == "0b0"

    def test_float_raises_type_error(self):
        """Floats should raise a TypeError."""
        with pytest.raises(TypeError):
            decimal_to_binary_iterative(16.16)

    def test_string_raises_type_error(self):
        """Strings should raise a TypeError."""
        with pytest.raises(TypeError):
            decimal_to_binary_iterative("0xfffff")


class TestDecimalToBinaryRecursiveHelper:
    """Tests for decimal_to_binary_recursive_helper."""

    @pytest.mark.parametrize(
        ("decimal", "expected"),
        [
            (0, "0"),
            (1, "1"),
            (2, "10"),
            (72, "1001000"),
            (1000, "1111101000"),
        ],
    )
    def test_positive_integers(self, decimal, expected):
        """Positive integers should convert to a binary string without prefix."""
        assert decimal_to_binary_recursive_helper(decimal) == expected

    def test_string_input_is_coerced(self):
        """Numeric strings should be coerced to int and converted."""
        assert decimal_to_binary_recursive_helper("72") == "1001000"

    def test_non_numeric_string_raises_value_error(self):
        """Non-numeric strings should raise a ValueError."""
        with pytest.raises(ValueError):
            decimal_to_binary_recursive_helper("number")

    def test_zero_and_one_boundary(self):
        """Zero and one are the recursion exit cases."""
        assert decimal_to_binary_recursive_helper(0) == "0"
        assert decimal_to_binary_recursive_helper(1) == "1"


class TestDecimalToBinaryRecursive:
    """Tests for decimal_to_binary_recursive."""

    @pytest.mark.parametrize(
        ("number", "expected"),
        [
            (0, "0b0"),
            (1, "0b1"),
            (40, "0b101000"),
            (1000, "0b1111101000"),
        ],
    )
    def test_positive_integers(self, number, expected):
        """Positive integers should produce a '0b' prefixed binary string."""
        assert decimal_to_binary_recursive(number) == expected

    @pytest.mark.parametrize(
        ("number", "expected"),
        [
            (-1, "-0b1"),
            (-40, "-0b101000"),
            (-1000, "-0b1111101000"),
        ],
    )
    def test_negative_integers(self, number, expected):
        """Negative integers should produce a '-0b' prefixed binary string."""
        assert decimal_to_binary_recursive(number) == expected

    def test_string_input_is_accepted(self):
        """Numeric strings should be accepted and converted."""
        assert decimal_to_binary_recursive("40") == "0b101000"

    def test_whitespace_is_stripped(self):
        """Leading/trailing whitespace should be stripped before conversion."""
        assert decimal_to_binary_recursive("  40  ") == "0b101000"

    def test_float_raises_value_error(self):
        """Floats should raise a ValueError."""
        with pytest.raises(ValueError):
            decimal_to_binary_recursive(40.8)

    def test_non_numeric_string_raises_value_error(self):
        """Non-numeric strings should raise a ValueError."""
        with pytest.raises(ValueError):
            decimal_to_binary_recursive("forty")

    def test_empty_string_raises_value_error(self):
        """An empty string should raise a ValueError."""
        with pytest.raises(ValueError):
            decimal_to_binary_recursive("")

    def test_whitespace_only_raises_value_error(self):
        """A whitespace-only string should raise a ValueError."""
        with pytest.raises(ValueError):
            decimal_to_binary_recursive("   ")
